355:function scrollToEditPrice(serial: string, exec: AdbExec, ops: ScreenOp[]): string | null {
356:	let prev = "";
357:	for (let page = 0; page < 8; page++) {
358:		if (stopRequested()) return null;
359:		const xml = dumpXml(serial, exec);
360:		if (editPriceReady(parseNodes(xml), CONFIRM_EDIT)) return xml;
361:		const key = parseNodes(xml)
362:			.map((node) => node.text)
363:			.filter(Boolean)
364:			.slice(0, 8)
365:			.join("|");
366:		if (page > 0 && key !== "" && key === prev) return null;
367:		prev = key;
368:		swipeStep(serial, exec, ops, "가격 칸이 아직 안 보여서");
369:	}
370:	return null;
371:}
