378:function confirmMatchingPrice(
379:	serial: string,
380:	exec: AdbExec,
381:	ops: ScreenOp[],
382:	want: number,
383:	label: string,
384:	reason: string,
385:): boolean {
386:	if (imeShown(serial, exec) || keyboardOpen(dumpXml(serial, exec))) {
387:		act(
388:			serial,
389:			{ cmd: "key", action: "키보드를 닫음", reason: "확정 버튼이 가려져서" },
390:			() => {
391:				exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_BACK"]);
392:				sleep(400);
393:			},
394:			() => "키보드만 닫으려고 뒤로 감",
395:		);
396:	}
397:	if (imeShown(serial, exec)) return false;
398:	let xml = dumpXml(serial, exec);
399:	if (keyboardOpen(xml)) return false;
400:	const shown = parseNodes(xml);
401:	const field = editPriceField(shown) ?? priceField(shown);
402:	if (!field || parseWon(field.text) !== want) {
403:		noteSkip(label, `가격 칸이 ${field ? field.text : "없음"}이라 ${want.toLocaleString("ko-KR")}원 확정을 안 누름`);
404:		return false;
405:	}
406:	let nodes = parseNodes(xml);
407:	let confirm =
408:		label === CONFIRM_BUMP ? confirmBump(nodes) : nodes.find((node) => node.text === label || node.desc === label);
409:	for (let page = 0; !confirm && label === CONFIRM_EDIT && page < 4; page++) {
410:		swipeStep(serial, exec, ops, "수정 완료가 아직 안 보여서");
411:		xml = dumpXml(serial, exec);
412:		const again = editPriceField(parseNodes(xml));
413:		if (again && parseWon(again.text) !== want) return false;
414:		nodes = parseNodes(xml);
415:		confirm = nodes.find((node) => node.text === label || node.desc === label);
416:	}
417:	if (!confirm || forbiddenLabel(confirm.text, confirm.desc)) return false;
418:	// 중단 요청은 확정 직전에서만 본다. 칸에 쓴 값은 그만두기로 버린다.
419:	if (stopRequested()) return false;
