183:function bumpOne(
184:	serial: string,
185:	exec: AdbExec,
186:	ops: ScreenOp[],
187:	item: BatchItem,
188:	dry: boolean,
189:	book?: BumpBook,
190:): "bump" | "skip" | "stop" | "gone" {
191:	const title = item.title;
192:	const price = item.proposedPrice;
193:	if (stopRequested()) return "stop";
194:	let sheet: string | null = null;
195:	// 탭이 움직이는 목록에 떨어져 창이 안 열릴 수 있다. 멈춘 화면을 다시 읽어 한 번 더 누른다.
196:	for (let attempt = 0; attempt < 2 && !sheet; attempt++) {
197:		const xml = attempt === 0 ? dumpXml(serial, exec) : settledXml(serial, exec);
198:		const node = cardBump(parseNodes(xml), title);
199:		// 처음 읽은 화면에 카드가 없으면 앞선 동작으로 목록이 움직인 것이다. 눌러 보지 않았으니 건너뛰지 않고 다시 찾게 돌려준다.
200:		if (!node) return attempt === 0 ? "gone" : "skip";
201:		const point = center(node);
202:		tap(
203:			serial,
204:			exec,
205:			ops,
206:			point.x,
207:			point.y,
208:			"카드 끌어올리기",
209:			`「${title}」을 ${price.toLocaleString("ko-KR")}원으로 끌어올리려고`,
210:		);
211:		if (stopRequested()) return "stop";
212:		sheet = waitFor(serial, exec, (text) => onBumpSheet(text) || cooldownTip(text), attempt === 0 ? 3000 : 8000);
213:	}
214:	if (!sheet || cooldownTip(sheet)) {
215:		nowCooldown(item.id, sheet, book);
216:		backToSales(serial, exec, ops);
217:		return "skip";
218:	}
219:	// 목록이 다시 그려지는 사이 다른 카드를 눌렀을 수 있다. 연 창의 제목이 다르면 아무것도 바꾸지 않고 닫는다.
220:	if (!showsTitle(sheet, title)) {
221:		noteSkip(title, "연 끌어올리기 창의 제목이 달라서");
222:		backToSales(serial, exec, ops);
223:		return "skip";
224:	}
225:	const ready = ensurePrice(serial, exec, ops, sheet, price, dry);
226:	if (ready === "stop") return "stop";
227:	if (dry) {
228:		backToSales(serial, exec, ops);
229:		return ready === "skip" ? "skip" : "bump";
230:	}
231:	if (ready === "skip") {
232:		backToSales(serial, exec, ops);
233:		return "skip";
234:	}
235:	// 가격을 하나도 확정하지 않은 채로 멈춘다. 그만두기를 먼저 누른다.
236:	if (stopRequested()) {
237:		backToSales(serial, exec, ops);
238:		return "stop";
239:	}
240:	if (
241:		!confirmMatchingPrice(
242:			serial,
243:			exec,
244:			ops,
245:			price,
246:			CONFIRM_BUMP,
247:			`「${title}」 ${price.toLocaleString("ko-KR")}원 확정`,
248:		)
249:	) {
250:		backToSales(serial, exec, ops);
251:		return "stop";
252:	}
253:	recordBumped(item.id, book);
254:	backToSales(serial, exec, ops);
255:	return "bump";
256:}
