611:function waitFor(serial: string, exec: AdbExec, pred: (xml: string) => boolean, ms: number): string | null {
612:	const log = journal;
613:	const startMs = log?.now() ?? 0;
614:	const start = Date.now();
615:	let found: string | null = null;
616:	while (Date.now() - start < ms) {
617:		if (stopRequested()) break;
618:		const xml = dumpXml(serial, exec, true);
619:		if (pred(xml)) {
620:			found = xml;
621:			break;
622:		}
623:		sleep(350);
624:	}
625:	const endMs = log?.now() ?? 0;
626:	log?.next(
627:		{
628:			cmd: "wait",
629:			action: "화면을 기다림",
630:			reason: `${ms}ms 안에 기대한 화면이 되기를 기다려서`,
631:			result: found ? "기대한 화면이 됨" : stopRequested() ? "중단 요청으로 멈춤" : "기다려도 안 바뀜",
632:			ok: found !== null,
633:		},
634:		{ startMs, endMs },
635:	);
636:	return found;
637:}
