639:function dumpXml(serial: string, exec: AdbExec, fresh = false): string {
640:	if (!fresh && screen && screen.serial === serial && Date.now() - screen.at < SCREEN_REUSE_MS) return screen.xml;
641:	const log = serial === journalSerial ? journal : null;
642:	const startMs = log?.now() ?? 0;
643:	const xml = dumpScreen(serial, exec);
644:	const endMs = log?.now() ?? 0;
645:	log?.next(
646:		{
647:			cmd: "dump",
648:			action: "화면 덤프",
649:			reason: "지금 화면을 읽으려고",
650:			target: "",
651:			result: `${xml.length}바이트`,
652:			ok: xml.length > 0,
653:		},
654:		{ startMs, endMs },
655:	);
656:	screen = xml.length > 0 ? { serial, xml, at: Date.now() } : null;
657:	return xml;
658:}
