729: * 중간에 실패하거나 멈춰도 급한 글이 먼저 처리돼 있다. 끌어올리기 대상은 노출이 오래된 글이라 대부분 아래쪽에 있어서
730: * 맨 위로 되돌아가는 두 번째 걷기가 필요 없다.
731: */
732:function walkApproved(
733:	serial: string,
734:	exec: AdbExec,
735:	ops: ScreenOp[],
736:	batch: BatchFile,
737:	listPrices?: ReadonlyMap<string, number>,
738:	book?: BumpBook,
739:): Tally {
740:	const tally: Tally = { bumped: 0, pricedOnly: 0, skipped: 0, already: 0, stop: false };
741:	const pending = new Map(batch.items.map((item) => [item.title, item]));
742:	for (const item of batch.items) {
743:		const listed = listPrices?.get(item.id);
744:		if (listed === undefined || !alreadyAppliedToday(listed, item.proposedPrice, item.snapshot.price)) continue;
745:		tally.skipped += 1;
746:		tally.already += 1;
747:		noteSkip(item.title, "목록 가격이 승인된 오늘 가격과 같아서");
748:		pending.delete(item.title);
749:	}
750:	if (pending.size === 0) return tally;
751:	walkUp(serial, exec, ops, pending, tally, book);
752:	return tally;
753:}
