509:function titleAbove(nodes: ScreenNode[], bump: ScreenNode): string {
510:	const title = nodes
511:		.filter(
512:			(node) =>
513:				node.text &&
514:				node.y <= bump.y &&
515:				node.y > bump.y - 420 &&
516:				!node.text.includes("·") &&
517:				!/^[\d,]+원?$/.test(node.text) &&
518:				node.text !== "판매중" &&
519:				node.text !== "판매관리" &&
520:				node.text !== "원",
521:		)
522:		.sort((a, b) => b.y - a.y)[0];
523:	return title?.text ?? "";
524:}
