480:function openReadySheet(serial: string, exec: AdbExec, ops: ScreenOp[]): { xml: string; title: string } | null {
481:	const seen = new Set<string>();
482:	for (let page = 0; page < 12; page++) {
483:		if (stopRequested()) return null;
484:		let xml = dumpXml(serial, exec);
485:		if (cooldownTip(xml)) {
486:			backToSales(serial, exec, ops);
487:			xml = dumpXml(serial, exec);
488:		}
489:		const nodes = parseNodes(xml);
490:		const bumps = nodes.filter((node) => node.desc === "끌어올리기" && !forbiddenLabel(node.text, node.desc));
491:		let tapped = false;
492:		for (const bump of bumps) {
493:			const title = titleAbove(nodes, bump);
494:			if (!title || seen.has(title)) continue;
495:			seen.add(title);
496:			const point = center(bump);
497:			tap(serial, exec, ops, point.x, point.y, "카드 끌어올리기", `「${title}」 끌어올리기 창의 가격만 읽으려고`);
498:			const next = waitFor(serial, exec, (text) => onBumpSheet(text) || cooldownTip(text), 5000);
499:			if (next && onBumpSheet(next)) return { xml: next, title };
500:			backToSales(serial, exec, ops);
501:			tapped = true;
502:			break;
503:		}
504:		if (!tapped) swipeUp(serial, exec, ops, "이 화면의 끌어올리기는 대기 중이라 다음 글을 보러");
505:	}
506:	return null;
507:}
