549:function readSheet(xml: string, title: string): { ok: true; price: number } | { ok: false; message: string } {
550:	if (!onBumpSheet(xml)) return { ok: false, message: "끌어올리기 창이 아니에요" };
551:	const field = priceField(parseNodes(xml));
552:	if (!field) return { ok: false, message: "가격 칸이 없어요" };
553:	if (title && !xml.includes(title)) return { ok: false, message: "연 글의 제목이 덤프에 없어요" };
554:	return { ok: true, price: parseWon(field.text) };
555:}
