535:function moreFor(nodes: ScreenNode[], title: string): ScreenNode | null {
536:	const titleNode = nodes.find((node) => node.text === title);
537:	if (!titleNode) return null;
538:	return (
539:		nodes.find(
540:			(node) =>
541:				node.desc === "더보기" &&
542:				!forbiddenLabel(node.text, node.desc) &&
543:				node.y >= titleNode.y - 160 &&
544:				node.y < titleNode.y + 420,
545:		) ?? null
546:	);
547:}
