557:function openSales(serial: string, exec: AdbExec) {
558:	const xml = dumpXml(serial, exec);
559:	if (onSales(xml)) return;
560:	let opened = false;
561:	act(
562:		serial,
563:		{ cmd: "open", action: "판매관리를 염", reason: "판매중 목록이 아니라서" },
564:		() => {
565:			exec(["-s", serial, "shell", "am", "start", "-a", "android.intent.action.VIEW", "-d", KARROT_SALES]);
566:			sleep(800);
567:		},
