580:function backToSales(serial: string, exec: AdbExec, ops: ScreenOp[]) {
581:	for (let i = 0; i < 4; i++) {
582:		const xml = dumpXml(serial, exec);
583:		if (xml.includes("판매관리") && !xml.includes("그만두기")) return;
584:		const discard = parseNodes(xml).find((node) => node.text === "그만두기");
585:		if (discard) {
586:			const at = center(discard);
587:			act(
588:				serial,
589:				{ cmd: "tap", action: "그만두기를 누름", reason: "바꾼 가격이 저장되면 안 되어서" },
590:				() => {
591:					exec(["-s", serial, "shell", "input", "tap", String(at.x), String(at.y)]);
592:					sleep(400);
593:				},
594:				() => "수정을 저장하지 않고 닫음",
595:			);
596:			continue;
597:		}
598:		act(
599:			serial,
600:			{ cmd: "back", action: "뒤로 감", reason: "판매중 목록으로 돌아가려고" },
601:			() => {
602:				ops.push({ kind: "back" });
603:				exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_BACK"]);
604:				sleep(400);
605:			},
606:			() => (dumpXml(serial, exec).includes("판매관리") ? "판매관리로 돌아옴" : "아직 다른 화면"),
607:		);
608:	}
609:}
