677:function tap(serial: string, exec: AdbExec, ops: ScreenOp[], x: number, y: number, label: string, reason = label) {
678:	if (forbiddenLabel(label, label)) {
679:		noteSkip(label, "누르지 않는 버튼이라서");
680:		return;
681:	}
682:	act(
683:		serial,
684:		{ cmd: "tap", action: `${label}을 누름`, reason, target: `${x},${y}` },
685:		() => {
686:			ops.push({ kind: "tap", x, y, label });
687:			exec(["-s", serial, "shell", "input", "tap", String(x), String(y)]);
688:			sleep(500);
689:		},
690:		() => "탭을 보냈어요",
691:	);
692:}
