698:/** 목록 끝까지 민다. 노출이 최근인 글이 위, 오래된 글이 아래다. */
699:function scrollToEdge(serial: string, exec: AdbExec, ops: ScreenOp[], edge: "top" | "bottom") {
700:	let prev = "";
701:	let stuck = 0;
702:	for (let page = 0; page < 24; page++) {
703:		if (stopRequested()) return;
704:		const parsed = parseSalesDump(page === 0 ? dumpXml(serial, exec) : settledXml(serial, exec));
705:		const cards = parsed.ok ? parsed.cards : [];
706:		const head = (edge === "top" ? cards[0]?.title : cards[cards.length - 1]?.title) ?? "";
707:		if (page > 0 && head !== "" && head === prev) {
708:			stuck += 1;
709:			if (stuck >= 2) return;
710:		} else {
711:			stuck = 0;
712:		}
713:		prev = head;
714:		swipeList(
715:			serial,
716:			exec,
717:			ops,
718:			edge === "top" ? "판매중 목록을 맨 위에서 읽으려고" : "판매중 목록을 맨 아래에서 읽으려고",
719:			edge === "top" ? "up" : "bottom",
720:		);
721:	}
722:}
723:
724:type Tally = { bumped: number; pricedOnly: number; skipped: number; already: number; stop: boolean };
725:
726:/**
727: * 승인 글을 폰에서 처리한다. 당근 목록은 마지막 노출이 최근인 글이 위, 오래된 글이 아래다. 맨 아래로 내려간 뒤
728: * 위로 한 번만 걸으며 만나는 대로 처리한다(끌어올리기와 가격만 수정을 함께). 노출이 가장 오래된 글이 먼저 끝나고,
729: * 중간에 실패하거나 멈춰도 급한 글이 먼저 처리돼 있다. 끌어올리기 대상은 노출이 오래된 글이라 대부분 아래쪽에 있어서
730: * 맨 위로 되돌아가는 두 번째 걷기가 필요 없다.
731: */
732:function walkApproved(
733:	serial: string,
734:	exec: AdbExec,
735:	ops: ScreenOp[],
736:	batch: BatchFile,
737:	listPrices?: ReadonlyMap<string, number>,
738:	book?: BumpBook,
739:): Tally {
740:	const tally: Tally = { bumped: 0, pricedOnly: 0, skipped: 0, already: 0, stop: false };
741:	const pending = new Map(batch.items.map((item) => [item.title, item]));
742:	for (const item of batch.items) {
743:		const listed = listPrices?.get(item.id);
744:		if (listed === undefined || !alreadyAppliedToday(listed, item.proposedPrice, item.snapshot.price)) continue;
745:		tally.skipped += 1;
746:		tally.already += 1;
747:		noteSkip(item.title, "목록 가격이 승인된 오늘 가격과 같아서");
748:		pending.delete(item.title);
749:	}
750:	if (pending.size === 0) return tally;
751:	walkUp(serial, exec, ops, pending, tally, book);
752:	return tally;
753:}
754:
755:/** 맨 아래에서 위로 걷는 한 판을 되풀이하는 상한. 끌올이 하루 6개라 한 판에 하나씩만 끝나는 최악에도 모자라지 않는다. */
756:const MAX_WALK_PASSES = 8;
757:
758:/**
759: * 맨 아래에서 위로 걸으며 남은 글을 처리한다. 끌올하거나 창을 닫고 돌아오면 목록이 맨 위로 되돌아가
760: * 위로만 걷는 한 판은 아래·가운데 글에 닿지 못한 채 끝난다(2026-11-07 가격만 12건·끌올 1건 놓침).

760: * 위로만 걷는 한 판은 아래·가운데 글에 닿지 못한 채 끝난다(2026-11-07 가격만 12건·끌올 1건 놓침).
761: * 한 판에서 하나라도 처리했는데 남은 글이 있으면 맨 아래부터 다시 걷는다. 진전이 없으면 멈춘다.
762: */
763:function walkUp(
764:	serial: string,
765:	exec: AdbExec,
766:	ops: ScreenOp[],
767:	pending: Map<string, BatchItem>,
768:	tally: Tally,
769:	book?: BumpBook,
770:) {
771:	for (let pass = 0; pass < MAX_WALK_PASSES && pending.size > 0; pass++) {
772:		const before = pending.size;
773:		walkPass(serial, exec, ops, pending, tally, book);
774:		if (tally.stop || pending.size === before) break;
775:	}
776:	for (const title of pending.keys()) {
777:		tally.skipped += 1;
778:		noteSkip(title, "판매중 목록에서 제목을 못 찾음");
779:	}
780:}
781:
782:function walkPass(
783:	serial: string,
784:	exec: AdbExec,
785:	ops: ScreenOp[],
786:	pending: Map<string, BatchItem>,
787:	tally: Tally,
788:	book?: BumpBook,
789:) {
790:	scrollToEdge(serial, exec, ops, "bottom");
791:	let prev = "";
792:	let stuck = 0;
793:	let page = 0;
794:	for (let turn = 0; turn < 60 && page < 24 && pending.size > 0; turn++) {
795:		if (stopRequested()) {
796:			tally.stop = true;
797:			return;
798:		}
799:		let reread = false;
800:		const xml = settledXml(serial, exec);
801:		const nodes = parseNodes(xml);
802:		const parsed = parseSalesDump(xml);
803:		if (parsed.ok) {
804:			// 아래에서 위로 걸을 때는 화면 아래 카드부터. 오래 노출 안 된 글이 먼저다.
805:			for (const card of [...parsed.cards].reverse()) {
806:				const item = pending.get(card.title);
807:				if (!item) continue;
808:				// 예약중 글은 거래 약속이 잡혀 있다. 저장소가 아직 모르더라도 폰 화면이 예약중이면 건드리지 않는다.
809:				if (card.reserved) {
810:					tally.skipped += 1;
811:					noteSkip(item.title, "당근에서 예약중이라서");
812:					book?.recordReserved?.(item.id);
813:					pending.delete(item.title);
814:					continue;
815:				}
816:				if (alreadyAppliedToday(card.price, item.proposedPrice, item.snapshot.price)) {
817:					tally.skipped += 1;
818:					tally.already += 1;
819:					noteSkip(item.title, "카드 가격이 승인된 오늘 가격과 같아서");
820:					pending.delete(item.title);
821:					continue;
822:				}
823:				const verdict = guardSnapshot(item.snapshot, card);
824:				if (!verdict.run) {
825:					tally.skipped += 1;
826:					noteSkip(item.title, "가격이 승인 때와 달라서");
827:					pending.delete(item.title);
828:					continue;
829:				}
830:				const visible = item.action === "bump" ? cardBump(nodes, item.title) : moreFor(nodes, item.title);
831:				if (!visible) continue;
832:				const done =
833:					item.action === "bump"
834:						? bumpOne(serial, exec, ops, item, false, book)
835:						: priceOne(serial, exec, ops, item, false);
836:				// 카드가 화면에서 사라졌다. 목록이 움직였으니 글은 남겨 두고, 다시 읽어 찾는다.
837:				if (done === "gone") {
838:					reread = true;
839:					break;
840:				}
841:				pending.delete(item.title);
842:				if (done === "stop") {
843:					backToSales(serial, exec, ops);
844:					tally.stop = true;
845:					return;
846:				}
847:				if (done === "bump") tally.bumped += 1;
848:				else if (done === "price") tally.pricedOnly += 1;
849:				else tally.skipped += 1;
850:				if (stopRequested()) {
851:					tally.stop = true;
852:					return;
853:				}
854:				// 끌어올린 글은 목록 맨 위로 옮겨 가 화면 배치가 바뀐다. 이 덤프의 나머지 카드는 믿지 않고 다시 읽는다.
855:				if (done === "bump") {
856:					reread = true;
857:					break;
858:				}
859:			}
860:		}
861:		if (pending.size === 0) break;
862:		if (reread) continue;
863:		const key = parsed.ok ? parsed.cards.map((card) => card.title).join("|") : "";
864:		if (page > 0 && key !== "" && key === prev) {
865:			stuck += 1;
866:			if (stuck >= 2) break;
867:		} else {
868:			stuck = 0;
869:		}
870:		prev = key;
871:		swipeList(serial, exec, ops, "남은 승인 글을 보러", "back");
872:		page += 1;
873:	}
874:}
