Implement bumpedAt reconciliation with day granularity:

```
function ingestedBumpedAt(card, prior, now) {
  const minutes = card.bumpAgoMinutes;
  if (minutes !== null && minutes !== undefined && Number.isFinite(minutes)) return new Date(now - minutes*60000).toISOString();
  const days = card.bumpAgoDays;
  if (days === null || days === undefined || !Number.isFinite(days)) return prior;
  const coarse = new Date(now - days*86400000).toISOString();
  if (prior !== null) {
    const elapsedDays = Math.floor((now - Date.parse(prior)) / 86400000);
    if (Number.isFinite(elapsedDays) && elapsedDays === Math.round(days)) return prior;
  }
  return coarse;
}
