			":bumped_at": bump.bumpedAt,
			":bump_count": bumpCount,
			":next_bump_at": next,
		});
}

/** 폰이 보여 준 다음 시각을 남긴 글. 관측값만 폰 목록을 다시 읽어도 지킨다. */
private observedNextBumps(): Map<string, boolean> {
	const rows = this.db.prepare(`SELECT title, next_bump_observed FROM listing`).all() as {
		title: string;
		next_bump_observed: number | null;
	}[];
	return new Map(rows.map((row) => [row.title, row.next_bump_observed === 1]));
}

if (!names.has("next_bump_at")) this.db.exec("ALTER TABLE listing ADD COLUMN next_bump_at TEXT");
if (!names.has("next_bump_observed"))
	this.db.exec("ALTER TABLE listing ADD COLUMN next_bump_observed INTEGER NOT NULL DEFAULT 0");

