146:export function runApprovedOnPhone(
147:	batch: BatchFile,
148:	base: AdbExec = adbExec,
149:	listPrices?: ReadonlyMap<string, number>,
150:	options: RunOptions = {},
151:): PhoneRun {
152:	const exec = watchMoves(base);
153:	screen = null;
154:	const serial = (options.findSerial ?? findPhoneSerial)();
155:	if (!serial) return fail(PHONE_MISSING, false);
156:	const ops: ScreenOp[] = [];
157:	journal = options.log ?? openActionLog();
158:	journalSerial = serial;
159:	stop = false;
160:	wake(serial, exec);
161:	if (readLocked(serial, exec)) return fail("폰이 잠겨 있어요. PIN은 넣지 않아요", false);
162:	openSales(serial, exec);
163:	const tally = walkApproved(serial, exec, ops, batch, listPrices, options.book);
164:	const bumped = tally.bumped;
165:	const pricedOnly = tally.pricedOnly;
166:	const skipped = tally.skipped;
167:	const already = tally.already;
168:	if (tally.stop) return stopped(bumped, pricedOnly, skipped, ops, stopRequested());
169:	const applied = already > 0 ? `이미 오늘 가격인 ${already}건은 건너뛰었어요` : "";
170:	const summary = `끌어올리기 ${bumped} · 가격만 ${pricedOnly} · 건너뜀 ${skipped}`;
171:	return {
172:		bumped,
173:		pricedOnly,
174:		skipped,
175:		note: applied === "" ? summary : `${summary}. ${applied}`,
176:		touched: ops.length > 0,
177:		confirmed: ops.some((op) => op.kind === "tap" && (op.label === CONFIRM_BUMP || op.label === CONFIRM_EDIT)),
178:		ops,
179:		stopped: false,
180:	};
181:}
