258:function priceOne(
259:	serial: string,
260:	exec: AdbExec,
261:	ops: ScreenOp[],
262:	item: BatchItem,
263:	dry: boolean,
264:): "price" | "skip" | "stop" | "gone" {
265:	const title = item.title;
266:	const price = item.proposedPrice;
267:	if (stopRequested()) return "stop";
268:	let menu: string | null = null;
269:	// 탭이 움직이는 목록에 떨어져 메뉴가 안 열릴 수 있다. 멈춘 화면을 다시 읽어 한 번 더 누른다.
270:	for (let attempt = 0; attempt < 2 && !menu; attempt++) {
271:		const xml = attempt === 0 ? dumpXml(serial, exec) : settledXml(serial, exec);
272:		const more = moreFor(parseNodes(xml), title);
273:		if (!more) return attempt === 0 ? "gone" : "skip";
274:		const at = center(more);
275:		tap(serial, exec, ops, at.x, at.y, "더보기", `「${title}」 가격만 ${price.toLocaleString("ko-KR")}원으로 맞추려고`);
276:		menu = waitFor(serial, exec, (text) => text.includes("게시글 수정"), 4000);
277:	}
278:	if (!menu) {
279:		backToSales(serial, exec, ops);
280:		return "skip";
281:	}
282:	const edit = parseNodes(menu).find((node) => node.text === "게시글 수정");
283:	if (!edit || forbiddenLabel(edit.text, edit.desc)) {
284:		backToSales(serial, exec, ops);
285:		return "stop";
286:	}
287:	const editAt = center(edit);
288:	tap(serial, exec, ops, editAt.x, editAt.y, "게시글 수정", `「${title}」 수정 창을 열려고`);
289:	const form = scrollToEditPrice(serial, exec, ops);
290:	if (!form) {
291:		noteSkip(title, "수정 창에서 가격 칸을 못 찾아서");
292:		backToSales(serial, exec, ops);
293:		return "skip";
294:	}
295:	const ready = ensurePrice(serial, exec, ops, form, price, dry, true);
296:	if (ready === "stop") {
297:		backToSales(serial, exec, ops);
298:		return "skip";
299:	}
300:	if (dry) {
301:		backToSales(serial, exec, ops);
302:		return ready === "skip" ? "skip" : "price";
303:	}
304:	if (ready === "skip") {
305:		backToSales(serial, exec, ops);
306:		return "skip";
307:	}
308:	if (stopRequested()) {
309:		backToSales(serial, exec, ops);
310:		return "stop";
311:	}
312:	if (
313:		!confirmMatchingPrice(
314:			serial,
315:			exec,
316:			ops,
317:			price,
318:			CONFIRM_EDIT,
319:			`「${title}」 ${price.toLocaleString("ko-KR")}원 저장`,
320:		)
321:	) {
322:		backToSales(serial, exec, ops);
323:		return "stop";
324:	}
325:	backToSales(serial, exec, ops);
326:	return "price";
327:}
