329:/** 성공한 끌어올리기의 횟수·쿨타임을 남긴다. 횟수는 이전+1, 다음 시각은 추정표. */
330:function recordBumped(listingId: string, book?: BumpBook) {
331:	if (!book) return;
332:	const bumpedAt = new Date().toISOString();
333:	const bumpCount = book.previousBumpCount(listingId) + 1;
334:	book.recordBump(listingId, { bumpedAt, bumpCount, nextBumpAt: nextBumpAt(bumpedAt, bumpCount) });
335:}
336:
337:/** 폰에 뜬 남은 시간 문구를 읽어 다음 끌어올림 시각을 남긴다. 문구를 못 읽으면 아무것도 하지 않는다. */
338:function nowCooldown(listingId: string, xml: string | null, book?: BumpBook) {
339:	if (!book || !xml) return;
340:	const text = cooldownText(xml);
341:	if (!text) return;
342:	const next = parseCooldownText(text, new Date());
343:	if (next) book.recordCooldown(listingId, next);
344:}
345:
346:/** 화면에서 쿨타임 문구를 꺼낸다. 판매팁·끌어올릴 수 있어요 문구가 있는 노드 중 가장 긴 글. */
347:export function cooldownText(xml: string): string | null {
348:	const texts = parseNodes(xml)
349:		.flatMap((node) => [node.text, node.desc])
350:		.filter((text) => text !== "" && cooldownTip(text))
351:		.sort((left, right) => right.length - left.length);
352:	return texts[0] ?? null;
353:}
