373:function imeShown(serial: string, exec: AdbExec): boolean {
374:	const blob = exec(["-s", serial, "shell", "dumpsys", "input_method"]).stdout;
375:	return blob.includes("mInputShown=true") || /mImeWindowVis=[1-9]/.test(blob) || keyboardOpen(blob);
