434:function ensurePrice(
435:	serial: string,
436:	exec: AdbExec,
437:	ops: ScreenOp[],
438:	xml: string,
439:	want: number,
440:	dry: boolean,
441:	currency = false,
442:): "ok" | "skip" | "stop" {
443:	const nodes = parseNodes(xml);
444:	const field = currency ? editPriceField(nodes) : (priceField(nodes) ?? editPriceField(nodes));
445:	if (!field) return "stop";
446:	if (parseWon(field.text) === want) return "ok";
447:	if (dry) return "ok";
448:	// 지우기·입력은 확정 전이라 버릴 수 있다. 중단이면 아예 쓰지 않는다.
449:	if (stopRequested()) return "stop";
450:	let changed = false;
451:	act(
452:		serial,
453:		{
454:			cmd: "input",
455:			action: `가격 칸을 ${want.toLocaleString("ko-KR")}원으로 바꿈`,
456:			reason: `칸이 ${field.text}이라서`,
457:			target: String(want),
458:		},
459:		() => {
460:			const at = center(field);
461:			ops.push({ kind: "tap", x: at.x, y: at.y, label: "가격" });
462:			exec(["-s", serial, "shell", "input", "tap", String(at.x), String(at.y)]);
463:			sleep(300);
464:			for (let i = 0; i < 8; i++) key(serial, exec, "KEYCODE_DEL");
465:			sleep(200);
466:			for (const digit of String(want)) {
467:				if (stopRequested()) break;
468:				key(serial, exec, `KEYCODE_${digit}`);
469:			}
470:			sleep(400);
471:			const againNodes = parseNodes(dumpXml(serial, exec));
472:			const again = currency ? editPriceField(againNodes) : (priceField(againNodes) ?? editPriceField(againNodes));
473:			changed = Boolean(again && parseWon(again.text) === want);
474:		},
475:		() => (changed ? `${want.toLocaleString("ko-KR")}원으로 바뀜` : "가격이 안 바뀌어서 확정하지 않음"),
476:	);
477:	return changed ? "ok" : "stop";
478:}
