526:/** 화면에 그 글의 제목이 있는가. 긴 제목은 칸에서 잘려도 노드 text 는 온전하다. */
527:function showsTitle(xml: string, title: string): boolean {
528:	return parseNodes(xml).some((node) => node.text.includes(title) || node.desc.includes(title));
529:}
530:
531:function cooldownTip(xml: string): boolean {
532:	return xml.includes("판매팁") || xml.includes("끌어올릴 수 있어요");
533:}
