698:/** 목록 끝까지 민다. 노출이 최근인 글이 위, 오래된 글이 아래다. */
699:function scrollToEdge(serial: string, exec: AdbExec, ops: ScreenOp[], edge: "top" | "bottom") {
700:	let prev = "";
701:	let stuck = 0;
702:	for (let page = 0; page < 24; page++) {
703:		if (stopRequested()) return;
704:		const parsed = parseSalesDump(page === 0 ? dumpXml(serial, exec) : settledXml(serial, exec));
705:		const cards = parsed.ok ? parsed.cards : [];
706:		const head = (edge === "top" ? cards[0]?.title : cards[cards.length - 1]?.title) ?? "";
707:		if (page > 0 && head !== "" && head === prev) {
708:			stuck += 1;
709:			if (stuck >= 2) return;
710:		} else {
711:			stuck = 0;
712:		}
713:		prev = head;
714:		swipeList(
715:			serial,
716:			exec,
717:			ops,
718:			edge === "top" ? "판매중 목록을 맨 위에서 읽으려고" : "판매중 목록을 맨 아래에서 읽으려고",
719:			edge === "top" ? "up" : "bottom",
720:		);
721:	}
722:}
