/** 폰 문구 `끌올 N일·시간·분 전`을 지금 기준 ISO로. 문구가 없으면 이전 시각을 이어 쓴다. */
function ingestedBumpedAt(card: DumpCard, prior: string | null, now: number): string | null {
	const minutes = card.bumpAgoMinutes ?? (card.bumpAgoDays === null ? null : Math.round(card.bumpAgoDays * 1_440));
	if (minutes === null || !Number.isFinite(minutes)) return prior;
	return new Date(now - minutes * 60_000).toISOString();
}

/**
 * 다음 끌올 가능 시각. 폰이 보여 준 관측값이 있으면 그 값보다 늦은 추정으로만 덮는다.
 * 관측을 추정으로 앞당기지는 않는다.
 */
function ingestedNextBumpAt(input: {
	priorNext: string | null;
	bumpedAt: string | null;
	bumpCount: number | null;
}): string | null {
	const count = input.bumpCount;
	const estimate =
		input.bumpedAt === null || count === null || count < 1 ? null : estimateNextBumpAt(input.bumpedAt, count);
	return laterOf(input.priorNext, estimate);
}

function laterOf(left: string | null, right: string | null): string | null {
	if (left === null) return right;
	if (right === null) return left;
	return Date.parse(left) >= Date.parse(right) ? left : right;
}

edits.newText:
/**
 * 폰 문구 `끌올 N일·시간·분 전`을 지금 기준 ISO로. 문구가 없으면 이전 시각을 이어 쓴다.
 * 하루 단위 문구는 그날 어디쯤인지 말해 주지 않는다. 이미 아는 시각이 그 문구와 같은 날에 들어가면
 * 되짚은 값으로 덮지 않고 그대로 쓴다(2026-11-11 새벽 끌올이 낮 시각으로 밀려 쿨타임이 어긋났다).
 */
function ingestedBumpedAt(card: DumpCard, prior: string | null, now: number): string | null {
	const minutes = card.bumpAgoMinutes;
	if (minutes !== null && Number.isFinite(minutes)) return new Date(now - minutes * 60_000).toISOString();
	const days = card.bumpAgoDays;
	if (days === null || !Number.isFinite(days)) return prior;
	if (prior !== null) {
		const elapsedDays = Math.floor((now - Date.parse(prior)) / 86_400_000);
		if (Number.isFinite(elapsedDays) && elapsedDays === Math.round(days)) return prior;
	}
	return new Date(now - days * 86_400_000).toISOString();
}

/**
 * 다음 끌올 가능 시각. 폰이 보여 준 관측값이 있으면 그 값보다 늦은 추정으로만 덮는다.
 * 관측을 추정으로 앞당기지는 않지만, 지난 회차가 그은 추정은 지키지 않고 새 추정으로 다시 긋는다
 * (옛 추정이 남아 끌올이 빠졌다).
 */
function ingestedNextBumpAt(input: {
	priorNext: string | null;
	priorObserved: boolean;
	bumpedAt: string | null;
	bumpCount: number | null;
}): { at: string | null; observed: boolean } {
	const count = input.bumpCount;
	const estimate =
		input.bumpedAt === null || count === null || count < 1 ? null : estimateNextBumpAt(input.bumpedAt, count);
	if (input.priorObserved && input.priorNext !== null) {
		if (estimate === null || Date.parse(input.priorNext) >= Date.parse(estimate)) {
			return { at: input.priorNext, observed: true };
		}
	}
	return { at: estimate ?? input.priorNext, observed: false };
}

