/**
 * 판매중 목록으로 돌아간다. 창을 닫으면 당근이 홈 피드로 떨어질 때가 있다. 거기서 back 을 또 누르면 앱 밖(앞 앱)으로
 * 나가므로, 한 번만 뒤로 간 뒤 판매관리가 아니면 back 을 더 누르지 않고 판매관리 딥링크로 다시 연다.
 */
function backToSales(serial: string, exec: AdbExec, ops: ScreenOp[]) {
	const xml = dumpXml(serial, exec);
	if (salesReady(xml)) return;
	const discard = parseNodes(xml).find((node) => node.text === "그만두기");
	if (discard) {
		const at = center(discard);
		act(
			serial,
			{ cmd: "tap", action: "그만두기를 누름", reason: "바꾼 가격이 저장되면 안 되어서" },
			() => {
				exec(["-s", serial, "shell", "input", "tap", String(at.x), String(at.y)]);
				sleep(400);
			},
			() => "수정을 저장하지 않고 닫음",
		);
	} else {
		act(
			serial,
			{ cmd: "back", action: "뒤로 감", reason: "판매중 목록으로 돌아가려고" },
			() => {
				ops.push({ kind: "back" });
				exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_BACK"]);
				sleep(400);
			},
			() => (salesReady(dumpXml(serial, exec)) ? "판매관리로 돌아옴" : "아직 다른 화면"),
		);
	}
	// 그만두기 뒤에도, back 한 번 뒤에도 판매관리가 아니면 딥링크로 연다(홈 피드·다른 화면에서 앱을 나가지 않게).
	openSales(serial, exec);
}

function salesReady(xml: string): boolean {
	return xml.includes("판매관리") && !xml.includes("그만두기");
}

